  &reftitle.examples;

   Exemplo de Yar_Server::handle


<?php
class API {
    /**
     * O bloco de documentação é exibido na página de informações do serviço.
     * @param string $parameter
     * @return string
     */
    public function some_method($parameter, $option = "foo") {
        return "some_method";
    }

    protected function client_can_not_see() {
    }
}

$service = new Yar_Server(new API());
$service->handle();
?>




   Personalizando a página de informações do serviço com __info (a
   partir do Yar 2.3.0)


<?php
class API {
    public function some_method($parameter, $option = "foo") {
        return "some_method";
    }

    /*
     * Deve ser protegido. É chamado em requisições GET com a marcação da
     * página que o Yar renderizaria, e a string retornada é
     * enviada ao cliente em seu lugar.
     */
    protected function __info($markup) {
        return "Hello world";
    }
}

$service = new Yar_Server(new API());
$service->handle();
?>
